#!/usr/bin/env python3
"""
Proof-of-Concept: Cleartext HTTP/2 (h2c) Downgrade

This script demonstrates the h2c downgrade vulnerability by establishing a cleartext
HTTP/2 connection over TCP port 80. It sends the h2c connection preface and a simple
GET request, showing that HTTP/2 frames are transmitted without TLS encryption.

Usage:
    python poc_cleartext_h2c_downgrade.py <target_host> [target_port]

Note: This is for educational and security testing purposes only.
Ensure you have explicit permission to test the target system.
"""

import sys
import socket
import struct

# The HTTP/2 connection preface for cleartext (h2c)
# Defined in RFC 9113 Section 3.4
H2C_PREFACE = b'PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n'

def send_h2c_request(host, port=80):
    """
    Establishes a cleartext HTTP/2 connection and sends a GET request.
    """
    print(f"[*] Connecting to {host}:{port} over cleartext TCP...")
    
    try:
        # Step 1: Create a raw TCP socket
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)
        sock.connect((host, port))
        
        # Step 2: Send the h2c connection preface
        print("[*] Sending h2c connection preface...")
        sock.sendall(H2C_PREFACE)
        
        # Step 3: Send a SETTINGS frame (required by RFC 9113)
        # Frame format: Length (3 bytes) | Type (1 byte) | Flags (1 byte) | Stream ID (4 bytes) | Payload
        settings_frame = struct.pack('!IBI', 0, 0x04, 0)  # Length=0, Type=SETTINGS(4), Flags=0, StreamID=0
        sock.sendall(settings_frame)
        
        # Step 4: Send a HEADERS frame for GET / on Stream 1
        # Construct a simple HEADERS frame with :method, :path, :scheme, :authority
        headers = [
            (':method', 'GET'),
            (':path', '/'),
            (':scheme', 'http'),
            (':authority', host)
        ]
        
        # Note: In a real implementation, you would use HPACK encoding.
        # For this PoC, we'll send a minimal HEADERS frame with raw pseudo-headers
        # This is a simplified representation. A full implementation would use the `h2` library.
        headers_payload = b''
        for name, value in headers:
            headers_payload += name.encode() + b'\r\n' + value.encode() + b'\r\n'
        
        # HEADERS frame: Length | Type(0x01) | Flags(0x04 for END_HEADERS) | StreamID(1) | Payload
        headers_frame = struct.pack('!IBI', len(headers_payload), 0x01, 0x04) + struct.pack('!I', 1) + headers_payload
        sock.sendall(headers_frame)
        
        print("[*] Sent h2c request. Waiting for response...")
        
        # Step 5: Receive and display the response
        response = b''
        while True:
            chunk = sock.recv(4096)
            if not chunk:
                break
            response += chunk
            # Stop after receiving a reasonable amount of data
            if len(response) > 1024:
                break
        
        print("[+] Received response (first 512 bytes):")
        print(response[:512].decode('utf-8', errors='ignore'))
        print("\n[!] VULNERABILITY DEMONSTRATED:")
        print("    The HTTP/2 connection was established over cleartext TCP.")
        print("    All frames, headers, and data are visible to network eavesdroppers.")
        print("    This bypasses TLS encryption, exposing sensitive information.")
        
    except socket.timeout:
        print("[-] Connection timed out. Server may not support h2c.")
    except ConnectionRefusedError:
        print("[-] Connection refused. Ensure the target supports h2c on port 80.")
    except Exception as e:
        print(f"[-] Error: {e}")
    finally:
        sock.close()

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: python poc_cleartext_h2c_downgrade.py <target_host> [target_port]")
        sys.exit(1)
    
    host = sys.argv[1]
    port = int(sys.argv[2]) if len(sys.argv) > 2 else 80
    
    send_h2c_request(host, port)